CREATE MEMORY TABLE PUBLIC.FILE_PATH_HISTORY(COMMIT_TIME TIMESTAMP,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,FILE_TYPE VARCHAR(32),BLOB_OBJECT_ID VARCHAR(40) NOT NULL,COMMIT_OBJECT_ID VARCHAR(40) NOT NULL,FILE_PATH VARCHAR(500) NOT NULL,REPOSITORY_NAME VARCHAR(255) NOT NULL);
ALTER TABLE PUBLIC.FILE_PATH_HISTORY ALTER COLUMN ID RESTART WITH 1;
CREATE INDEX IDX_FPH_REPO_PATH ON PUBLIC.FILE_PATH_HISTORY(REPOSITORY_NAME,FILE_PATH);
CREATE INDEX IDX_FPH_REPO_COMMIT ON PUBLIC.FILE_PATH_HISTORY(REPOSITORY_NAME,COMMIT_OBJECT_ID);
CREATE INDEX IDX_FPH_REPO_BLOB ON PUBLIC.FILE_PATH_HISTORY(REPOSITORY_NAME,BLOB_OBJECT_ID);
CREATE MEMORY TABLE PUBLIC.GIT_COMMIT_INDEX(COMMIT_TIME TIMESTAMP,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,OBJECT_ID VARCHAR(40) NOT NULL,CHANGED_PATHS VARCHAR(65535),COMMIT_MESSAGE VARCHAR(65535),PARENT_IDS VARCHAR(65535),AUTHOR_EMAIL VARCHAR(255),AUTHOR_NAME VARCHAR(255),REPOSITORY_NAME VARCHAR(255) NOT NULL,UNIQUE(OBJECT_ID));
ALTER TABLE PUBLIC.GIT_COMMIT_INDEX ALTER COLUMN ID RESTART WITH 2;
CREATE INDEX IDX_COMMIT_REPO ON PUBLIC.GIT_COMMIT_INDEX(REPOSITORY_NAME);
CREATE INDEX IDX_COMMIT_REPO_TIME ON PUBLIC.GIT_COMMIT_INDEX(REPOSITORY_NAME,COMMIT_TIME);
CREATE INDEX IDX_COMMIT_AUTHOR ON PUBLIC.GIT_COMMIT_INDEX(AUTHOR_NAME,AUTHOR_EMAIL);
CREATE MEMORY TABLE PUBLIC.GIT_OBJECTS(OBJECT_TYPE INTEGER NOT NULL,CREATED_AT TIMESTAMP NOT NULL,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,OBJECT_SIZE BIGINT NOT NULL,OBJECT_ID VARCHAR(40) NOT NULL,DATA BLOB(1G) NOT NULL,REPOSITORY_NAME VARCHAR(255) NOT NULL,UNIQUE(OBJECT_ID));
ALTER TABLE PUBLIC.GIT_OBJECTS ALTER COLUMN ID RESTART WITH 1;
CREATE INDEX IDX_GIT_OBJ_TYPE ON PUBLIC.GIT_OBJECTS(OBJECT_TYPE);
CREATE MEMORY TABLE PUBLIC.GIT_PACKS(CREATED_AT TIMESTAMP NOT NULL,FILE_SIZE BIGINT NOT NULL,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,DATA BLOB(1G) NOT NULL,PACK_EXTENSION VARCHAR(255) NOT NULL,PACK_NAME VARCHAR(255) NOT NULL,REPOSITORY_NAME VARCHAR(255) NOT NULL);
ALTER TABLE PUBLIC.GIT_PACKS ALTER COLUMN ID RESTART WITH 4;
CREATE INDEX IDX_PACK_REPO ON PUBLIC.GIT_PACKS(REPOSITORY_NAME);
CREATE INDEX IDX_PACK_REPO_NAME ON PUBLIC.GIT_PACKS(REPOSITORY_NAME,PACK_NAME);
CREATE MEMORY TABLE PUBLIC.GIT_REFLOG(ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,VERSION BIGINT NOT NULL,WHO_WHEN TIMESTAMP NOT NULL,NEW_ID VARCHAR(40),OLD_ID VARCHAR(40),MESSAGE VARCHAR(2048),REF_NAME VARCHAR(255) NOT NULL,REPOSITORY_NAME VARCHAR(255) NOT NULL,WHO_EMAIL VARCHAR(255),WHO_NAME VARCHAR(255));
ALTER TABLE PUBLIC.GIT_REFLOG ALTER COLUMN ID RESTART WITH 2;
CREATE INDEX IDX_REFLOG_REPO ON PUBLIC.GIT_REFLOG(REPOSITORY_NAME);
CREATE INDEX IDX_REFLOG_REPO_REF ON PUBLIC.GIT_REFLOG(REPOSITORY_NAME,REF_NAME);
CREATE MEMORY TABLE PUBLIC.GIT_REFS(IS_PEELED BOOLEAN,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,UPDATED_AT TIMESTAMP NOT NULL,VERSION BIGINT NOT NULL,OBJECT_ID VARCHAR(40),PEELED_OBJECT_ID VARCHAR(40),REF_NAME VARCHAR(512) NOT NULL,SYMBOLIC_TARGET VARCHAR(512),REPOSITORY_NAME VARCHAR(255) NOT NULL,UNIQUE(REPOSITORY_NAME,REF_NAME));
ALTER TABLE PUBLIC.GIT_REFS ALTER COLUMN ID RESTART WITH 1;
CREATE MEMORY TABLE PUBLIC.JAVA_BLOB_INDEX(HAS_EMBEDDING BOOLEAN,HAS_MAIN_METHOD BOOLEAN,LINE_COUNT INTEGER,COMMIT_DATE TIMESTAMP,ID BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL PRIMARY KEY,FILE_TYPE VARCHAR(32),TYPE_KIND VARCHAR(32),BLOB_OBJECT_ID VARCHAR(40) NOT NULL,COMMIT_OBJECT_ID VARCHAR(40) NOT NULL,VISIBILITY VARCHAR(64),PACKAGE_NAME VARCHAR(512),PROJECT_NAME VARCHAR(512),SIMPLE_CLASS_NAME VARCHAR(512),FILE_PATH VARCHAR(1024),TYPE_DOCUMENTATION VARCHAR(2000),ANNOTATIONS VARCHAR(65535),DECLARED_FIELDS VARCHAR(65535),DECLARED_METHODS VARCHAR(65535),DECLARED_TYPES VARCHAR(65535),EXTENDS_TYPES VARCHAR(65535),FULLY_QUALIFIED_NAMES VARCHAR(65535),IMPLEMENTS_TYPES VARCHAR(65535),IMPORT_STATEMENTS VARCHAR(65535),METHOD_SIGNATURES VARCHAR(65535),REFERENCED_TYPES VARCHAR(65535),SOURCE_SNIPPET VARCHAR(65535),STRING_LITERALS VARCHAR(65535),COMMIT_AUTHOR VARCHAR(255),REPOSITORY_NAME VARCHAR(255) NOT NULL,SEMANTIC_EMBEDDING BLOB(1G));
ALTER TABLE PUBLIC.JAVA_BLOB_INDEX ALTER COLUMN ID RESTART WITH 1;
CREATE INDEX IDX_BLOB_REPO ON PUBLIC.JAVA_BLOB_INDEX(REPOSITORY_NAME);
CREATE INDEX IDX_BLOB_BLOB_OID ON PUBLIC.JAVA_BLOB_INDEX(BLOB_OBJECT_ID);
CREATE INDEX IDX_BLOB_COMMIT_OID ON PUBLIC.JAVA_BLOB_INDEX(COMMIT_OBJECT_ID);
